            );
            document.getElementById('mizuki-action').innerText = SafeGetValue(characterData, '状态.美月.行为', '未知');
            document.getElementById('mizuki-outfit').innerText = SafeGetValue(characterData, '状态.美月.装扮', '未知');
            document.getElementById('mizuki-body').innerText = SafeGetValue(characterData, '状态.美月.身体', '未知');
            document.getElementById('mizuki-pregnancy').innerText = SafeGetValue(characterData, '状态.美月.妊娠') === 'true' ? '是' : '否';
            document.getElementById('mizuki-enjo-count').innerText = SafeGetValue(characterData, '经历.美月.援交次数', '0');
            document.getElementById('mizuki-creampie-count').innerText = SafeGetValue(characterData, '经历.美月.被内射次数', '0');

            // 雪村凛状态更新
            updateProgressBar(
                'rin-affection-bar',
                'rin-affection',
                SafeGetValue(characterData, '关系.凛好感度'),
                0, 200
            );
            document.getElementById('rin-action').innerText = SafeGetValue(characterData, '状态.凛.行为', '未知');
            document.getElementById('rin-outfit').innerText = SafeGetValue(characterData, '状态.凛.装扮', '未知');
            document.getElementById('rin-body').innerText = SafeGetValue(characterData, '状态.凛.身体', '未知');
            document.getElementById('rin-pregnancy').innerText = SafeGetValue(characterData, '状态.凛.妊娠') === 'true' ? '是' : '否';
